import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String filterExpr = req.getParameter("filter");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("csv|json|xml")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query with user-supplied filter expression
            String baseQuery = "SELECT r.id, r.title, r.created_at, r.data, u.email " +
                             "FROM reports r JOIN users u ON r.owner_id = u.id " +
                             "WHERE r.id = '" + reportId + "'";

            if (filterExpr != null && !filterExpr.isEmpty()) {
                // Apply additional filter - supports complex expressions
                baseQuery += " AND (" + filterExpr + ")";
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(baseQuery);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getString("id"));
                row.put("title", rs.getString("title"));
                row.put("created_at", rs.getString("created_at"));
                row.put("data", rs.getString("data"));
                row.put("email", rs.getString("email"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Return error details for debugging
            resp.setStatus(500);
            JSONObject error = new JSONObject();
            error.put("error", e.getMessage());
            error.put("sqlState", e.getSQLState());
            resp.setContentType("application/json");
            resp.getWriter().write(error.toString());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch export - reads report IDs from body
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        try {
            JSONObject payload = new JSONObject(body.toString());
            JSONArray ids = payload.getJSONArray("report_ids");
            String ownerFilter = payload.optString("owner", null);

            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            StringBuilder queryBuilder = new StringBuilder(
                "SELECT r.id, r.title, r.data FROM reports r WHERE r.id IN (");

            for (int i = 0; i < ids.length(); i++) {
                if (i > 0) queryBuilder.append(",");
                queryBuilder.append("'").append(ids.getString(i)).append("'");
            }
            queryBuilder.append(")");

            if (ownerFilter != null) {
                queryBuilder.append(" AND r.owner_id = '").append(ownerFilter).append("'");
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(queryBuilder.toString());

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getString("id"));
                row.put("title", rs.getString("title"));
                row.put("data", rs.getString("data"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
            conn.close();

        } catch (Exception e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"" + e.getMessage() + "\"}");
        }
    }
}
